import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A user name's role on the sheet: clerk, steward or viewer. A name with none is a clerk. */
export type Role = { user: string; role: string };

/** The sheet's settings: its clerk limit with two decimals (null when there is none) and its floor with two
 *  decimals (a claim's live due is at least it), and its terms in days (a claim is due by its date plus them), and its late percent with two decimals (an overdue claim's due gains,
 *  for each full 30 days overdue, the one in force on that boundary date of its figure), and its policy date (YYYY-MM-DD; "" when blank: the sheet's today — a claim
 *  dated before it rounds half up, one on or after it half to even), and its period numbering from (YYYY-MM-DD; "" when off — while the sheet's today is
 *  on or after it, a claim opened is numbered within its period), and the own terms in days of grades A, B and C ("" when the
 *  grade uses the sheet's terms; a claim's due-by is fixed when it is created, from its person's grade on its date), and its cap with
 *  two decimals ("" when there is none — a person's due-total is at most it), and its proof threshold with two decimals ("" when there is none — a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof), and its grace days ("" when off; not dated), and its note threshold with two decimals ("" when there is none — a claim whose due is
 *  above the one in force on its date cannot be opened with an empty note), and its entry date (YYYY-MM-DD; "" when off; not dated — while it is set, a new claim left without a date is dated it in place of the sheet's today), and the grace days of grades A, B and C ("" when none — an overdue claim's lateness counts from its due-by plus those of its person's grade on its date, in force on its date), and the proof thresholds of grades A, B and C with two decimals ("" when none — a claim of its person's grade on its date uses the one in force then in place of the sheet's), and its pot with two decimals ("" when there is none; not dated — shared out among the members of each balanced pool by their shares), and its parent sheet's id ("" when none; not dated — a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up), and its fiscal year start month (1 to 12; "1" unless set; not dated — a fiscal year starts on its first day in that month and is named FY<yyyy> by the calendar year that day falls in), and its alert threshold with two decimals ("" when off; not dated — a person whose due-total goes above it is alerted in the audit). Each of those is the value in force on the
 *  sheet's today; `dated` holds the values recorded for each setting that carries a figure, by key (floor, late-pct,
 *  terms, terms-A/B/C, clerk-limit, cap, proof-threshold, note-threshold, grace-A/B/C, proof-threshold-A/B/C), each from its from-date on (null: from the beginning of time; a null value is blank). */
export type Settings = { clerkLimit: string | null; floor: string; terms: string;
  latePct: string; policyDate: string; periodNumberingFrom: string;
  termsA: string; termsB: string; termsC: string; cap: string; proofThreshold: string;
  dated: Record<string, { from: string | null; value: string | null }[]>;
  permOpen: string; permSettle: string; permVoid: string; permReassign: string; permClose: string; permReopen: string;
  graceDays: string; noteThreshold: string; entryDate: string;
  graceA: string; graceB: string; graceC: string;
  proofThresholdA: string; proofThresholdB: string; proofThresholdC: string; pot: string; parent: string;
  fiscalStartMonth: string; alertThreshold: string };

/** The value of a dated setting in force on a date (YYYY-MM-DD): the one recorded with the latest from-date on or
 *  before it, else `start` (the sheet's starting value). */
/** A sheet, chosen by its id; everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys of the dated settings: those that carry a figure. */
    public static final String FLOOR = "floor", LATE_PCT = "late-pct", TERMS = "terms", CLERK_LIMIT = "clerk-limit",
            CAP = "cap", PROOF_THRESHOLD = "proof-threshold", NOTE_THRESHOLD = "note-threshold";

    /** The key of the grace days: undated, a whole number of days (null: off). */
    public static final String GRACE_DAYS = "grace-days";

    /** The key of the pot: undated, an amount with two decimals (null: none). */
    public static final String POT = "pot";

    /** The key of the alert threshold: undated, an amount with two decimals (null: off). */
    public static final String ALERT_THRESHOLD = "alert-threshold";

    /** The key of the parent sheet: undated, a sheet's id (null: none). A grade with no rate in force on a date on
     *  this sheet takes the parent's, then the parent's parent's, up to three levels up. */
    public static final String PARENT = "parent";

    /** The key of the fiscal year start month: undated, a month 1 to 12 (null: 1). */
    public static final String FISCAL_START_MONTH = "fiscal-start-month";

    /** The keys of the undated dates, as the settings form names them. */
    public static final String POLICY_DATE = "policy-date", PERIOD_NUMBERING_FROM = "period-numbering-from",
            ENTRY_DATE = "entry-date";

    /** The setting key of an action's entry in the permission matrix. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    @Id
    private String id;

    /** The sheet's today: every date decision and default date uses it, never the real clock. */
    @Column(nullable = false)
    private LocalDate today;

    /** Whether the sheet had been archived by the end of a date: it was archived while its today was on or before
     *  it (one archived before that was recorded, on any date). */
    public boolean archivedBy(LocalDate date) {
        return archived && (archivedOn == null || !archivedOn.isAfter(date));
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    /** The policy date in force: the one set, else the sheet's today. */
    public LocalDate policyDateInForce() {
        return policyDate != null ? policyDate : today;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;

