    /** The sheet as of the date: its settings then, archived only if it was by then, the date its today. */
    public Sheet sheet(Sheet sheet, LocalDate date) {
        return date == null ? sheet : settingLogs.sheetAsOf(sheet, date);
    }

    /** The sheet's people, in list order: as of a date, those then on the sheet in the places they hold now. */
    public List<Person> people(String sheetId, LocalDate date) {
        List<Person> now = people.findListed(sheetId);
        if (date == null) {
            return now;
        }
        Map<Long, Long> places = now.stream().collect(Collectors.toMap(Person::getId, Person::getPlace));
        return sorted(history.asOf(sheetId, Person.class, date, now, Person::getId),
                Comparator.<Person>comparingLong(p -> places.getOrDefault(p.getId(), p.getPlace())).thenComparing(Person::getId));
    }

    /** The sheet's dated grades of each person, by from-date, by person id. */
    public Map<Long, List<PersonGrade>> grades(String sheetId, LocalDate date) {
        if (date == null) {
            return grades.datedOnSheet(sheetId);
        return KINDS.get(type);
    }

    /** The entity's state, as recorded. */
    JsonNode stateOf(Object entity) {
        return json.valueToTree(entity);
    }

    String write(JsonNode state) {
        return json.writeValueAsString(state);
    }

    /**
     * The sheet's things of a type as they stood at the end of a date, in no particular order: each as its last
     * state saved while the sheet's today was on or before it; none deleted or not yet made by then. A thing with no
     * state recorded at all is taken as it stands now. Only worked out, never saved.
     *
     * @param current the sheet's things of the type as they stand now.
     */
    public <T> List<T> asOf(String sheetId, Class<T> type, LocalDate date, List<T> current, Function<T, Long> idOf) {
        Set<Long> recorded = new HashSet<>();
        Map<Long, String> then = new LinkedHashMap<>();
        jdbc.query("SELECT entity_id, made_on, state FROM entity_history WHERE sheet_id = ? AND kind = ? ORDER BY id",
                rs -> {
                    long id = rs.getLong(1);
                    recorded.add(id);
                    Date madeOn = rs.getDate(2);
                    if (!madeOn.toLocalDate().isAfter(date)) {
                        String state = rs.getString(3);
                        if (state == null) {
                            then.remove(id);
                        } else {
                            then.put(id, state);
                        }
                    }
                }, sheetId, kindOf(type));
        List<T> asOf = new ArrayList<>();
        for (T now : current) {
            if (!recorded.contains(idOf.apply(now))) {
                asOf.add(now);
            }
        }
        then.values().forEach(state -> asOf.add(json.readValue(state, type)));
        return asOf;
    }
}

